def verify_access_log(log_path: str, allowed_ips: list[str]) -> list[str]:
    """Kontrollerar åtkomstloggen och returnerar otillåtna IP-adresser."""
    tillatna = set(allowed_ips)
    otillatna = set()

    with open(log_path, encoding="utf-8") as f:
        for rad in f:
            if rad.strip():
                ip = rad.split()[0]
                if ip not in tillatna:
                    otillatna.add(ip)

    return sorted(otillatna)
