import csv

def parse_border_crossings(csv_path: str) -> list[dict]:
    """Parsar en CSV-fil med gränspassagedata.

    Returnerar en lista av dictar där numeriska värden konverterats
    till int/float och tomma fält blivit None.
    """
    def convert(value: str):
        value = value.strip()
        if not value:
            return None
        for typ in (int, float):
            try:
                return typ(value)
            except ValueError:
                pass
        return value

    with open(csv_path, newline="", encoding="utf-8-sig") as f:
        return [
            {key.strip(): convert(val) for key, val in row.items()}
            for row in csv.DictReader(f)
        ]
```

