import csv


def parse_border_crossings(csv_path: str) -> list[dict]:
    """
    Parsa en Frontex-CSV med gränspassager vid EU:s yttre gräns.

    Förväntade kolumner (normaliseras till snake_case):
    Border Type, Route, Nationality, Month, Year, Value

    Returnerar t.ex.:
    {"border_type": "Sea", "route": "Central Mediterranean Route",
     "nationality": "Syria", "month": 6, "year": 2023, "value": 1234}
    """
    result = []
    with open(csv_path, newline="", encoding="utf-8-sig") as f:
        for row in csv.DictReader(f):
            entry = {
                key.strip().lower().replace(" ", "_"): (value or "").strip()
                for key, value in row.items()
                if key
            }
            if not any(entry.values()):
                continue
            for field in ("month", "year", "value"):
                if entry.get(field, "").lstrip("-").isdigit():
                    entry[field] = int(entry[field])
            result.append(entry)
    return result
```

