from collections import defaultdict

def detect_intrusion(packet_log: list[dict]) -> list[dict]:
    """Identifiera misstänkta intrångsförsök i nätverksloggar.

    Förväntar paket med nycklarna: src_ip, dst_port, status.
    """
    PORT_SCAN_THRESHOLD = 10   # unika portar från samma IP
    BRUTE_FORCE_THRESHOLD = 5  # misslyckade anslutningar
    SENSITIVE_PORTS = {22, 23, 445, 3389}

    ports_per_ip = defaultdict(set)
    failed_per_ip = defaultdict(int)

    for packet in packet_log:
        src = packet.get("src_ip")
        if not src:
            continue
        ports_per_ip[src].add(packet.get("dst_port"))
        if packet.get("status") == "failed":
            failed_per_ip[src] += 1

    findings = []
    for ip, ports in ports_per_ip.items():
        if len(ports) >= PORT_SCAN_THRESHOLD:
            findings.append({
                "src_ip": ip,
                "type": "port_scan",
                "details": f"{len(ports)} unika portar kontaktade",
                "severity": "high" if ports & SENSITIVE_PORTS else "medium",
            })
        if failed_per_ip[ip] >= BRUTE_FORCE_THRESHOLD:
            findings.append({
                "src_ip": ip,
                "type": "brute_force",
                "details": f"{failed_per_ip[ip]} misslyckade försök",
                "severity": "high",
            })

    return findings
```

